<script>
document.addEventListener('DOMContentLoaded', function () {
    const overlay = document.getElementById('loginOverlay');
    const trigger = document.getElementById('loginTrigger');
    const close = document.getElementById('loginClose');
    const backdrop = document.getElementById('loginBackdrop');
    if (!overlay || !trigger) return;
    const openLogin = () => { overlay.classList.add('is-open'); overlay.setAttribute('aria-hidden', 'false'); trigger.setAttribute('aria-expanded', 'true'); const username = document.getElementById('username'); if (username) window.setTimeout(() => username.focus(), 50); };
    const closeLogin = () => { overlay.classList.remove('is-open'); overlay.setAttribute('aria-hidden', 'true'); trigger.setAttribute('aria-expanded', 'false'); trigger.focus(); };
    trigger.addEventListener('click', openLogin);
    if (close) close.addEventListener('click', closeLogin);
    if (backdrop) backdrop.addEventListener('click', closeLogin);
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && overlay.classList.contains('is-open')) closeLogin(); });
    if (overlay.querySelector('.alert-danger')) openLogin();
});
</script>
